```python
import math

def count_primes_sieve(n):
    """Sieve of Eratosthenes to count primes below n."""
    if n <= 2:
        return 0
    is_prime = [True] * n
    is_prime[0] = False
    is_prime[1] = False
    for i in range(2, int(math.isqrt(n)) + 1):
        if is_prime[i]:
            for j in range(i * i, n, i):
                is_prime[j] = False
    return sum(is_prime)

def count_primes_trial(n):
    """Trial division to count primes below n."""
    def is_prime_trial(k):
        if k < 2:
            return False
        if k == 2:
            return True
        if k % 2 == 0:
            return False
        for d in range(3, int(math.isqrt(k)) + 1, 2):
            if k % d == 0:
                return False
        return True

    count = 0
    for k in range(2, n):
        if is_prime_trial(k):
            count += 1
    return count

n = 10000
count_sieve = count_primes_sieve(n)
count_trial = count_primes_trial(n)

print(f"Sieve count: {count_sieve}")
print(f"Trial division count: {count_trial}")

if count_sieve == count_trial:
    print(f"VERIFIED score={count_sieve}")
else:
    print(f"MISMATCH: sieve={count_sieve}, trial={count_trial}")
