import itertools

def verify(ruler):
    if not ruler:
        return False
    if ruler[0] != 0:
        return False
    for a, b in zip(ruler, ruler[1:]):
        if b <= a:
            return False
    if len(set(ruler)) != len(ruler):
        return False
    n = len(ruler)
    diffs = set()
    for i in range(n):
        for j in range(i+1, n):
            d = ruler[j] - ruler[i]
            if d in diffs:
                return False
            diffs.add(d)
    return len(diffs) == n*(n-1)//2

def find_ruler():
    n_marks = 6
    for max_len in range(n_marks-1, 31):
        for interior in itertools.combinations(range(1, max_len), n_marks-2):
            ruler = (0,) + interior + (max_len,)
            if verify(ruler):
                return ruler, max_len
    return None, None

ruler, length = find_ruler()
if ruler and len(ruler) == 6 and ruler[0] == 0 and verify(ruler):
    print(f"VERIFIED score={length}")
else:
    print("FAILED")
